styl:
.ig { max-width: 20px;
  margin-left: 6px; }
@media screen and (max-width: 600px) {
  .ig { width: 20px !important; }
}
.you { max-width: 24px;
  margin: 0 6px; }
@media screen and (max-width: 600px) {
  .you { width: 24px !important; }
}
.twitter { max-width: 24px;
  margin: 0 6px; }
@media screen and (max-width: 600px) {
  .twitter { width: 24px !important; }
}
.fb { max-width: 24px;
  margin-right: 6px; }
@media screen and (max-width: 600px) {
  .fb { width: 24px !important; }
}
.socials { display: inline-block;
  font-size: 0;
  margin: 0 auto; }
@media screen and (max-width: 600px) {
  .socials { width: 100% !important; }
}
.socials a { display: inline-block;
  vertical-align: middle;
  margin: 0 10px; }
@media screen and (max-width: 600px) {
  .socials a { margin-bottom: 10px !important; }
}
.soc-icon { float: none !important;
  max-width: 24px; }
